SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'system-design-capstone') AND order_index = 2 AND is_deleted = false LIMIT 1), 'The progress service: validation & monotonic updates', 'sanity', 'lesson-sdc-2-1', 1
