-- challenge chal_quiz_sdc_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_sdc_211', (SELECT id FROM catalog.course WHERE public_id = 'system-design-capstone'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'system-design-capstone') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdc-2-1' AND is_deleted = false LIMIT 1), 'progress-service-quiz', 'Monotonic progress and one event per real change', 'Two pieces of evidence from the progress service: a late update from an old tab that lowered a finished lesson, and a leaderboard that counted one lesson completion three times.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdc_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdc_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdc_211'), 'The progress handler stores a lesson percent with:

UPDATE lesson_progress SET percent = $3, updated_at = now()
WHERE user_id = $1 AND lesson_id = $2;

API log for one learner (laptop tab and an old phone tab):
09:14:02.118 PATCH /progress lesson=sql-3 percent=100 -> 200 (laptop)
09:14:02.904 PATCH /progress lesson=sql-3 percent=60  -> 200 (phone, sent at 09:13:40, retried after a network drop)

SELECT percent FROM lesson_progress WHERE user_id = ''u_an'' AND lesson_id = ''sql-3'';  -> 60

Statement: "Changing the assignment to SET percent = GREATEST(percent, $3) keeps the stored value at 100 when the 60 arrives after the 100, without any lock taken by the application."', 'single_choice'::question_type, 'True. GREATEST(percent, $3) reads the current value and computes the new one inside the same UPDATE, and PostgreSQL holds the row lock for the duration of that statement, so the late 60 cannot overwrite the 100: GREATEST(100, 60) = 100. That is exactly the monotonic rule (a lesson percent never goes down) expressed as one atomic statement. The common misconception is that you need to order requests by a client timestamp to fix this; client clocks and retries make timestamps unreliable, while "never lower it" needs no clock at all. To know whether to publish an event, add RETURNING and compare with the old value (or use WHERE percent < $3 and check the row count).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdc_211') AND order_index = 1)
    RETURNING id
)
