       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_212'), 'Each validation error, in the stated order', '{"catalog":{"courses":{"ts-101":{"lessons":["ts-1","ts-2","ts-3","ts-4"],"required":{"ts-3":["chal_ts_31","chal_ts_32"]}},"sql-201":{"lessons":["sql-1","sql-2","sql-3"],"required":{"sql-3":["chal_sql_33"]}}},"enrollments":{"u_an":["ts-101","sql-201"],"u_binh":["ts-101"],"u_chi":[]},"passed":{"u_an":["chal_ts_31","chal_ts_32"],"u_binh":["chal_ts_31"]}},"updates":[{"userId":"u_an","courseId":"ts-101","lessonId":"ts-1","percent":50.5},{"userId":"u_an","courseId":"go-301","lessonId":"go-1","percent":101},{"userId":"u_an","courseId":"go-301","lessonId":"go-1","percent":10},{"userId":"u_an","courseId":"ts-101","lessonId":"sql-1","percent":10},{"userId":"u_chi","courseId":"ts-101","lessonId":"ts-1","percent":10},{"userId":"u_binh","courseId":"ts-101","lessonId":"ts-3","percent":100},{"userId":"u_binh","courseId":"ts-101","lessonId":"ts-3","percent":90}]}', '"#1 u_an ts-101/ts-1 50.5 -> rejected INVALID_PERCENT\n#2 u_an go-301/go-1 101 -> rejected INVALID_PERCENT\n#3 u_an go-301/go-1 10 -> rejected UNKNOWN_COURSE\n#4 u_an ts-101/sql-1 10 -> rejected LESSON_NOT_IN_COURSE\n#5 u_chi ts-101/ts-1 10 -> rejected NOT_ENROLLED\n#6 u_binh ts-101/ts-3 100 -> rejected CHALLENGES_NOT_PASSED\n#7 u_binh ts-101/ts-3 90 -> applied v1 lesson 90 course 22\nevents: 1\nprogress.updated u_binh ts-101 ts-3 lesson=90 course=22 v=1\nstore:\nu_binh ts-101 v1 course=22 {\"ts-3\":90}"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_212'), 'A late lower update and a repeat neither lower progress nor publish', '{"catalog":{"courses":{"ts-101":{"lessons":["ts-1","ts-2","ts-3","ts-4"],"required":{"ts-3":["chal_ts_31","chal_ts_32"]}},"sql-201":{"lessons":["sql-1","sql-2","sql-3"],"required":{"sql-3":["chal_sql_33"]}}},"enrollments":{"u_an":["ts-101","sql-201"],"u_binh":["ts-101"],"u_chi":[]},"passed":{"u_an":["chal_ts_31","chal_ts_32"],"u_binh":["chal_ts_31"]}},"updates":[{"userId":"u_an","courseId":"ts-101","lessonId":"ts-1","percent":80},{"userId":"u_an","courseId":"ts-101","lessonId":"ts-1","percent":60},{"userId":"u_an","courseId":"ts-101","lessonId":"ts-1","percent":80},{"userId":"u_an","courseId":"ts-101","lessonId":"ts-1","percent":0},{"userId":"u_an","courseId":"ts-101","lessonId":"ts-2","percent":0},{"userId":"u_binh","courseId":"ts-101","lessonId":"ts-4","percent":0},{"userId":"u_an","courseId":"ts-101","lessonId":"ts-1","percent":81}]}', '"#1 u_an ts-101/ts-1 80 -> applied v1 lesson 80 course 20\n#2 u_an ts-101/ts-1 60 -> unchanged lesson 80\n#3 u_an ts-101/ts-1 80 -> unchanged lesson 80\n#4 u_an ts-101/ts-1 0 -> unchanged lesson 80\n#5 u_an ts-101/ts-2 0 -> unchanged lesson 0\n#6 u_binh ts-101/ts-4 0 -> unchanged lesson 0\n#7 u_an ts-101/ts-1 81 -> applied v2 lesson 81 course 20\nevents: 2\nprogress.updated u_an ts-101 ts-1 lesson=80 course=20 v=1\nprogress.updated u_an ts-101 ts-1 lesson=81 course=20 v=2\nstore:\nu_an ts-101 v2 course=20 {\"ts-1\":81}"', 3, false, true, 3),
