INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_232'), 'In-order events: points rules, top N and a watched learner', '{"top":3,"watch":["u_chi"],"batches":[{"week":"2026-W44","events":[{"eventId":"e1","type":"challenge.passed","userId":"u_an","learnerSeq":1,"week":"2026-W44","challengeId":"chal_e1","points":30},{"eventId":"e2","type":"challenge.passed","userId":"u_binh","learnerSeq":1,"week":"2026-W44","challengeId":"chal_e2","points":50},{"eventId":"e3","type":"progress.updated","userId":"u_an","learnerSeq":2,"week":"2026-W44","courseId":"ts-101","lessonId":"ts-3","lessonPercent":100,"coursePercent":40},{"eventId":"e4","type":"progress.updated","userId":"u_chi","learnerSeq":1,"week":"2026-W44","courseId":"ts-101","lessonId":"ts-3","lessonPercent":60,"coursePercent":20},{"eventId":"e5","type":"progress.updated","userId":"u_binh","learnerSeq":2,"week":"2026-W44","courseId":"ts-101","lessonId":"ts-3","lessonPercent":100,"coursePercent":100},{"eventId":"e6","type":"challenge.passed","userId":"u_an","learnerSeq":3,"week":"2026-W44","challengeId":"chal_e6","points":20}]}]}', '"batch 1 week 2026-W44: accepted 6, duplicate 0, stale 0, invalid 0, waiting 0\n  all-time: 1. u_binh 110, 2. u_an 60\n  2026-W44: 1. u_binh 110, 2. u_an 60\n  u_chi: all-time -, 2026-W44 -"', 3, true, false, 1),
