VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_322'), 'Two workers, limit 4: practice runs are shed at depth 2, exam submissions at depth 4', '{"config":{"limit":4,"practiceLimit":2,"workers":2,"defaultGradeMs":4000,"window":20},"jobs":[{"id":"e1","priority":"exam","at":0,"gradeMs":4000},{"id":"e2","priority":"exam","at":0,"gradeMs":4000},{"id":"p1","priority":"practice","at":100,"gradeMs":3000},{"id":"p2","priority":"practice","at":200,"gradeMs":3000},{"id":"p3","priority":"practice","at":300,"gradeMs":3000},{"id":"e3","priority":"exam","at":400,"gradeMs":5000},{"id":"e4","priority":"exam","at":500,"gradeMs":5000},{"id":"e5","priority":"exam","at":600,"gradeMs":5000},{"id":"p4","priority":"practice","at":700,"gradeMs":3000}]}', '{"exam":{"accepted":4,"rejected":1,"started":4,"maxWaitMs":3600,"avgWaitMs":1775},"practice":{"accepted":2,"rejected":2,"started":2,"maxWaitMs":8900,"avgWaitMs":8850},"invalid":0,"maxDepth":4,"depthAtEnd":0,"lost":0,"duplicateTakes":0,"unknownTakes":0,"lastFinishMs":12000,"retryAfter":{"exam":{"2":1},"practice":{"2":1,"6":1}},"firstRejections":["t=300 p3 practice 429 retry-after=2","t=600 e5 exam 429 retry-after=2","t=700 p4 practice 429 retry-after=6"]}', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_322'), 'Exam submissions are graded before older practice runs; waits are reported per priority', '{"config":{"limit":6,"practiceLimit":4,"workers":1,"defaultGradeMs":4000,"window":20},"jobs":[{"id":"p1","priority":"practice","at":0,"gradeMs":2000},{"id":"p2","priority":"practice","at":10,"gradeMs":2000},{"id":"p3","priority":"practice","at":20,"gradeMs":2000},{"id":"e1","priority":"exam","at":1000,"gradeMs":1500},{"id":"e2","priority":"exam","at":1500,"gradeMs":1500},{"id":"p4","priority":"practice","at":2500,"gradeMs":2000},{"id":"e3","priority":"exam","at":6000,"gradeMs":1000}]}', '{"exam":{"accepted":3,"rejected":0,"started":3,"maxWaitMs":2000,"avgWaitMs":1333},"practice":{"accepted":4,"rejected":0,"started":4,"maxWaitMs":7980,"avgWaitMs":5118},"invalid":0,"maxDepth":4,"depthAtEnd":0,"lost":0,"duplicateTakes":0,"unknownTakes":0,"lastFinishMs":12000,"retryAfter":{"exam":{},"practice":{}},"firstRejections":[]}', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_322'), 'Retry-After uses the average of the last `window` measured grading times, not the default', '{"config":{"limit":2,"practiceLimit":1,"workers":1,"defaultGradeMs":1000,"window":2},"jobs":[{"id":"e1","priority":"exam","at":0,"gradeMs":8000},{"id":"e2","priority":"exam","at":1,"gradeMs":8000},{"id":"e3","priority":"exam","at":2,"gradeMs":8000},{"id":"e4","priority":"exam","at":3,"gradeMs":8000},{"id":"p1","priority":"practice","at":4,"gradeMs":1000},{"id":"e5","priority":"exam","at":9000,"gradeMs":2000},{"id":"e6","priority":"exam","at":9001,"gradeMs":2000},{"id":"p2","priority":"practice","at":9002,"gradeMs":1000},{"id":"e7","priority":"exam","at":17000,"gradeMs":1000},{"id":"e8","priority":"exam","at":17001,"gradeMs":1000},{"id":"p3","priority":"practice","at":26000,"gradeMs":1000},{"id":"e9","priority":"exam","at":26001,"gradeMs":1000},{"id":"e10","priority":"exam","at":26002,"gradeMs":1000},{"id":"e11","priority":"exam","at":26003,"gradeMs":1000},{"id":"e12","priority":"exam","at":26004,"gradeMs":1000}]}', '{"exam":{"accepted":6,"rejected":6,"started":6,"maxWaitMs":15998,"avgWaitMs":8166},"practice":{"accepted":1,"rejected":2,"started":1,"maxWaitMs":2000,"avgWaitMs":2000},"invalid":0,"maxDepth":2,"depthAtEnd":0,"lost":0,"duplicateTakes":0,"unknownTakes":0,"lastFinishMs":29000,"retryAfter":{"exam":{"1":1,"5":3,"8":2},"practice":{"2":1,"16":1}},"firstRejections":["t=3 e4 exam 429 retry-after=1","t=4 p1 practice 429 retry-after=2","t=9001 e6 exam 429 retry-after=8","t=9002 p2 practice 429 retry-after=16","t=17001 e8 exam 429 retry-after=8","t=26002 e10 exam 429 retry-after=5","t=26003 e11 exam 429 retry-after=5","t=26004 e12 exam 429 retry-after=5"]}', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_322'), 'A full queue rejects the new exam submission instead of dropping an accepted practice run', '{"config":{"limit":3,"practiceLimit":2,"workers":1,"defaultGradeMs":3000,"window":10},"jobs":[{"id":"e0","priority":"exam","at":0,"gradeMs":6000},{"id":"p1","priority":"practice","at":10,"gradeMs":1000},{"id":"p2","priority":"practice","at":20,"gradeMs":1000},{"id":"e1","priority":"exam","at":30,"gradeMs":1000},{"id":"e2","priority":"exam","at":40,"gradeMs":1000},{"id":"e3","priority":"exam","at":50,"gradeMs":1000},{"id":"p3","priority":"practice","at":60,"gradeMs":1000}]}', '{"exam":{"accepted":2,"rejected":2,"started":2,"maxWaitMs":5970,"avgWaitMs":2985},"practice":{"accepted":2,"rejected":1,"started":2,"maxWaitMs":7980,"avgWaitMs":7485},"invalid":0,"maxDepth":3,"depthAtEnd":0,"lost":0,"duplicateTakes":0,"unknownTakes":0,"lastFinishMs":9000,"retryAfter":{"exam":{"3":2},"practice":{"6":1}},"firstRejections":["t=40 e2 exam 429 retry-after=3","t=50 e3 exam 429 retry-after=3","t=60 p3 practice 429 retry-after=6"]}', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_322'), 'Excess counts only the jobs above each threshold, so practice waits longer than exam', '{"config":{"limit":10,"practiceLimit":4,"workers":3,"defaultGradeMs":4500,"window":50},"jobs":[{"id":"run0","priority":"exam","at":0,"gradeMs":9000},{"id":"run1","priority":"exam","at":0,"gradeMs":9000},{"id":"run2","priority":"exam","at":0,"gradeMs":9000},{"id":"p0","priority":"practice","at":10,"gradeMs":4000},{"id":"p1","priority":"practice","at":11,"gradeMs":4000},{"id":"p2","priority":"practice","at":12,"gradeMs":4000},{"id":"p3","priority":"practice","at":13,"gradeMs":4000},{"id":"e0","priority":"exam","at":20,"gradeMs":4000},{"id":"e1","priority":"exam","at":21,"gradeMs":4000},{"id":"e2","priority":"exam","at":22,"gradeMs":4000},{"id":"e3","priority":"exam","at":23,"gradeMs":4000},{"id":"e4","priority":"exam","at":24,"gradeMs":4000},{"id":"e5","priority":"exam","at":25,"gradeMs":4000},{"id":"p-late","priority":"practice","at":30,"gradeMs":4000},{"id":"e-late","priority":"exam","at":31,"gradeMs":4000}]}', '{"exam":{"accepted":9,"rejected":1,"started":9,"maxWaitMs":12977,"avgWaitMs":7318},"practice":{"accepted":4,"rejected":1,"started":4,"maxWaitMs":20987,"avgWaitMs":17989},"invalid":0,"maxDepth":10,"depthAtEnd":0,"lost":0,"duplicateTakes":0,"unknownTakes":0,"lastFinishMs":25000,"retryAfter":{"exam":{"2":1},"practice":{"11":1}},"firstRejections":["t=30 p-late practice 429 retry-after=11","t=31 e-late exam 429 retry-after=2"]}', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_322'), 'Invalid jobs get 400 and are not counted; valid jobs around them are unaffected', '{"config":{"limit":4,"practiceLimit":2,"workers":2,"defaultGradeMs":4000,"window":20},"jobs":[{"id":"e1","priority":"exam","at":0,"gradeMs":1000},{"id":"","priority":"exam","at":1,"gradeMs":1000},{"id":42,"priority":"practice","at":2,"gradeMs":1000},{"id":"x1","priority":"urgent","at":3,"gradeMs":1000},{"id":"x2","at":4,"gradeMs":1000},{"id":"x3","priority":"EXAM","at":5,"gradeMs":1000},{"id":"p1","priority":"practice","at":6,"gradeMs":1000}]}', '{"exam":{"accepted":1,"rejected":0,"started":1,"maxWaitMs":0,"avgWaitMs":0},"practice":{"accepted":1,"rejected":0,"started":1,"maxWaitMs":0,"avgWaitMs":0},"invalid":5,"maxDepth":0,"depthAtEnd":0,"lost":0,"duplicateTakes":0,"unknownTakes":0,"lastFinishMs":1006,"retryAfter":{"exam":{},"practice":{}},"firstRejections":[]}', 2, false, true, 6),
