VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_332'), 'Leaderboard down: progress is saved, the update is deferred, then drained after recovery', '{"config":{"cache":{"timeoutMs":50,"failureThreshold":3,"openMs":10000},"leaderboard":{"timeoutMs":50,"failureThreshold":3,"openMs":10000},"drainBatch":10},"outages":{"leaderboard":[{"from":1000,"to":20000,"mode":"down","latencyMs":1}]},"drainEveryMs":5000,"untilMs":30000,"events":[{"at":0,"type":"progress","userId":"u1","lessonId":"l1","points":10},{"at":1000,"type":"progress","userId":"u1","lessonId":"l2","points":20},{"at":2000,"type":"progress","userId":"u2","lessonId":"l1","points":10},{"at":3000,"type":"progress","userId":"u3","lessonId":"l1","points":30},{"at":4000,"type":"progress","userId":"u1","lessonId":"l3","points":40},{"at":4500,"type":"top","n":3},{"at":26000,"type":"top","n":3}]}', '{"breakers":{"cache":"closed","leaderboard":"closed"},"pending":[],"leaderboardBehind":[],"calls":{"cache":5,"leaderboard":9},"degraded":5,"latencyTotalMs":212,"drained":3,"transitions":["t=3000 leaderboard closed -> open","t=25000 leaderboard open -> closed"],"results":["t=0 progress u1 l1 -> 200 total=10 19ms","t=1000 progress u1 l2 -> 200 total=30 degraded=leaderboard 18ms","t=2000 progress u2 l1 -> 200 total=10 degraded=leaderboard 18ms","t=3000 progress u3 l1 -> 200 total=30 degraded=leaderboard 18ms","t=4000 progress u1 l3 -> 200 total=70 degraded=leaderboard 17ms","t=4500 top 3 -> postgres degraded 120ms [u1:70,u3:30,u2:10]","t=25000 drain 3","t=26000 top 3 -> redis 2ms [u1:70,u3:30,u2:10]"]}', 3, true, false, 1),
