UPDATE course.lesson SET title = 'Recovery: rebuild the leaderboard after losing the cache', order_index = 2, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'system-design-capstone') AND order_index = 4 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdc-4-2' AND is_deleted = false LIMIT 1);
