VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_422'), 'Batch of 3: reads serve the snapshot while rebuilding, then the rebuilt boards', '{"batchSize":3,"snapshot":{"asOfSeq":5,"boards":{"alltime":[["u_ana",50],["u_dung",50],["u_binh",30]],"weekly:2026-W44":[["u_dung",50],["u_chi",20],["u_ana",10]]}},"log":[{"userId":"u_ana","week":"2026-W43","points":40},{"userId":"u_binh","week":"2026-W43","points":30},{"userId":"u_chi","week":"2026-W44","points":20},{"userId":"u_ana","week":"2026-W44","points":10},{"userId":"u_dung","week":"2026-W44","points":50},{"userId":"u_binh","week":"2026-W44","points":30},{"userId":"u_chi","week":"2026-W44","points":40},{"userId":"u_em","week":"2026-W44","points":15}],"script":[{"read":"alltime","n":3},{"tick":1},{"read":"alltime","n":3},{"tick":1},{"read":"weekly:2026-W44","n":2},{"tick":1},{"read":"alltime","n":5},{"read":"weekly:2026-W44","n":5}]}', '{"reads":[{"board":"alltime","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_ana",50],["u_dung",50],["u_binh",30]]},{"board":"alltime","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_ana",50],["u_dung",50],["u_binh",30]]},{"board":"weekly:2026-W44","n":2,"status":"rebuilding","asOfSeq":5,"top":[["u_dung",50],["u_chi",20]]},{"board":"alltime","n":5,"status":"ready","top":[["u_binh",60],["u_chi",60],["u_ana",50],["u_dung",50],["u_em",15]]},{"board":"weekly:2026-W44","n":5,"status":"ready","top":[["u_chi",60],["u_dung",50],["u_binh",30],["u_em",15],["u_ana",10]]}],"final":{"alltime":{"status":"ready","top":[["u_binh",60],["u_chi",60],["u_ana",50],["u_dung",50],["u_em",15]]},"weekly:2026-W43":{"status":"ready","top":[["u_ana",40],["u_binh",30]]},"weekly:2026-W44":{"status":"ready","top":[["u_chi",60],["u_dung",50],["u_binh",30],["u_em",15],["u_ana",10]]}}}', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_422'), 'Writes during the rebuild are caught up from the log before the switch', '{"batchSize":4,"snapshot":{"asOfSeq":5,"boards":{"alltime":[["u_ana",50],["u_dung",50],["u_binh",30]],"weekly:2026-W44":[["u_dung",50],["u_chi",20],["u_ana",10]]}},"log":[{"userId":"u_ana","week":"2026-W43","points":40},{"userId":"u_binh","week":"2026-W43","points":30},{"userId":"u_chi","week":"2026-W44","points":20},{"userId":"u_ana","week":"2026-W44","points":10},{"userId":"u_dung","week":"2026-W44","points":50},{"userId":"u_binh","week":"2026-W44","points":30},{"userId":"u_chi","week":"2026-W44","points":40},{"userId":"u_em","week":"2026-W44","points":15}],"script":[{"tick":1},{"write":{"userId":"u_em","week":"2026-W44","points":60}},{"read":"alltime","n":3},{"tick":1},{"write":{"userId":"u_binh","week":"2026-W44","points":25}},{"read":"alltime","n":3},{"tick":1},{"read":"alltime","n":6},{"tick":1},{"read":"alltime","n":6}]}', '{"reads":[{"board":"alltime","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_ana",50],["u_dung",50],["u_binh",30]]},{"board":"alltime","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_ana",50],["u_dung",50],["u_binh",30]]},{"board":"alltime","n":6,"status":"ready","top":[["u_binh",85],["u_em",75],["u_chi",60],["u_ana",50],["u_dung",50]]},{"board":"alltime","n":6,"status":"ready","top":[["u_binh",85],["u_em",75],["u_chi",60],["u_ana",50],["u_dung",50]]}],"final":{"alltime":{"status":"ready","top":[["u_binh",85],["u_em",75],["u_chi",60],["u_ana",50],["u_dung",50]]},"weekly:2026-W43":{"status":"ready","top":[["u_ana",40],["u_binh",30]]},"weekly:2026-W44":{"status":"ready","top":[["u_em",75],["u_chi",60],["u_binh",55],["u_dung",50],["u_ana",10]]}}}', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_422'), 'After the switch, live writes are applied once and a redelivered event is skipped', '{"batchSize":5,"snapshot":{"asOfSeq":5,"boards":{"alltime":[["u_ana",50],["u_dung",50],["u_binh",30]],"weekly:2026-W44":[["u_dung",50],["u_chi",20],["u_ana",10]]}},"log":[{"userId":"u_ana","week":"2026-W43","points":40},{"userId":"u_binh","week":"2026-W43","points":30},{"userId":"u_chi","week":"2026-W44","points":20},{"userId":"u_ana","week":"2026-W44","points":10},{"userId":"u_dung","week":"2026-W44","points":50},{"userId":"u_binh","week":"2026-W44","points":30},{"userId":"u_chi","week":"2026-W44","points":40},{"userId":"u_em","week":"2026-W44","points":15}],"script":[{"tick":2},{"read":"alltime","n":3},{"write":{"userId":"u_chi","week":"2026-W44","points":30}},{"redeliver":9},{"redeliver":2},{"write":{"userId":"u_em","week":"2026-W43","points":5}},{"redeliver":10},{"read":"alltime","n":10},{"read":"weekly:2026-W43","n":10},{"read":"weekly:2026-W44","n":3}]}', '{"reads":[{"board":"alltime","n":3,"status":"ready","top":[["u_binh",60],["u_chi",60],["u_ana",50]]},{"board":"alltime","n":10,"status":"ready","top":[["u_chi",90],["u_binh",60],["u_ana",50],["u_dung",50],["u_em",20]]},{"board":"weekly:2026-W43","n":10,"status":"ready","top":[["u_ana",40],["u_binh",30],["u_em",5]]},{"board":"weekly:2026-W44","n":3,"status":"ready","top":[["u_chi",90],["u_dung",50],["u_binh",30]]}],"final":{"alltime":{"status":"ready","top":[["u_chi",90],["u_binh",60],["u_ana",50],["u_dung",50],["u_em",20]]},"weekly:2026-W43":{"status":"ready","top":[["u_ana",40],["u_binh",30],["u_em",5]]},"weekly:2026-W44":{"status":"ready","top":[["u_chi",90],["u_dung",50],["u_binh",30],["u_em",15],["u_ana",10]]}}}', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_422'), 'Redis is lost again in the middle of the rebuild: start over from the first event', '{"batchSize":3,"snapshot":{"asOfSeq":5,"boards":{"alltime":[["u_ana",50],["u_dung",50],["u_binh",30]],"weekly:2026-W44":[["u_dung",50],["u_chi",20],["u_ana",10]]}},"log":[{"userId":"u_ana","week":"2026-W43","points":40},{"userId":"u_binh","week":"2026-W43","points":30},{"userId":"u_chi","week":"2026-W44","points":20},{"userId":"u_ana","week":"2026-W44","points":10},{"userId":"u_dung","week":"2026-W44","points":50},{"userId":"u_binh","week":"2026-W44","points":30},{"userId":"u_chi","week":"2026-W44","points":40},{"userId":"u_em","week":"2026-W44","points":15}],"script":[{"tick":2},{"flush":true},{"read":"alltime","n":3},{"tick":1},{"write":{"userId":"u_dung","week":"2026-W44","points":5}},{"tick":1},{"read":"alltime","n":3},{"tick":1},{"read":"alltime","n":3},{"tick":1},{"read":"alltime","n":10}]}', '{"reads":[{"board":"alltime","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_ana",50],["u_dung",50],["u_binh",30]]},{"board":"alltime","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_ana",50],["u_dung",50],["u_binh",30]]},{"board":"alltime","n":3,"status":"ready","top":[["u_binh",60],["u_chi",60],["u_dung",55]]},{"board":"alltime","n":10,"status":"ready","top":[["u_binh",60],["u_chi",60],["u_dung",55],["u_ana",50],["u_em",15]]}],"final":{"alltime":{"status":"ready","top":[["u_binh",60],["u_chi",60],["u_dung",55],["u_ana",50],["u_em",15]]},"weekly:2026-W43":{"status":"ready","top":[["u_ana",40],["u_binh",30]]},"weekly:2026-W44":{"status":"ready","top":[["u_chi",60],["u_dung",55],["u_binh",30],["u_em",15],["u_ana",10]]}}}', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_422'), 'Lost again after it was ready: back to the snapshot until the new rebuild switches', '{"batchSize":4,"snapshot":{"asOfSeq":5,"boards":{"alltime":[["u_ana",50],["u_dung",50],["u_binh",30]],"weekly:2026-W44":[["u_dung",50],["u_chi",20],["u_ana",10]]}},"log":[{"userId":"u_ana","week":"2026-W43","points":40},{"userId":"u_binh","week":"2026-W43","points":30},{"userId":"u_chi","week":"2026-W44","points":20},{"userId":"u_ana","week":"2026-W44","points":10},{"userId":"u_dung","week":"2026-W44","points":50},{"userId":"u_binh","week":"2026-W44","points":30},{"userId":"u_chi","week":"2026-W44","points":40},{"userId":"u_em","week":"2026-W44","points":15}],"script":[{"tick":2},{"read":"weekly:2026-W44","n":3},{"write":{"userId":"u_ana","week":"2026-W44","points":70}},{"flush":true},{"read":"weekly:2026-W44","n":3},{"write":{"userId":"u_binh","week":"2026-W43","points":10}},{"tick":1},{"read":"weekly:2026-W44","n":3},{"tick":2},{"read":"weekly:2026-W44","n":3},{"read":"weekly:2026-W43","n":3}]}', '{"reads":[{"board":"weekly:2026-W44","n":3,"status":"ready","top":[["u_chi",60],["u_dung",50],["u_binh",30]]},{"board":"weekly:2026-W44","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_dung",50],["u_chi",20],["u_ana",10]]},{"board":"weekly:2026-W44","n":3,"status":"rebuilding","asOfSeq":5,"top":[["u_dung",50],["u_chi",20],["u_ana",10]]},{"board":"weekly:2026-W44","n":3,"status":"ready","top":[["u_ana",80],["u_chi",60],["u_dung",50]]},{"board":"weekly:2026-W43","n":3,"status":"ready","top":[["u_ana",40],["u_binh",40]]}],"final":{"alltime":{"status":"ready","top":[["u_ana",120],["u_binh",70],["u_chi",60],["u_dung",50],["u_em",15]]},"weekly:2026-W43":{"status":"ready","top":[["u_ana",40],["u_binh",40]]},"weekly:2026-W44":{"status":"ready","top":[["u_ana",80],["u_chi",60],["u_dung",50],["u_binh",30],["u_em",15]]}}}', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_422'), 'Edge cases: empty log, a week the snapshot lacks, a week with no events', '{"batchSize":10,"snapshot":{"asOfSeq":0,"boards":{}},"log":[],"script":[{"read":"alltime","n":5},{"read":"weekly:2026-W44","n":5},{"tick":1},{"read":"alltime","n":5},{"read":"weekly:2026-W01","n":5},{"write":{"userId":"u_new","week":"2026-W44","points":10}},{"read":"weekly:2026-W44","n":1}]}', '{"reads":[{"board":"alltime","n":5,"status":"rebuilding","asOfSeq":0,"top":[]},{"board":"weekly:2026-W44","n":5,"status":"rebuilding","asOfSeq":0,"top":[]},{"board":"alltime","n":5,"status":"ready","top":[]},{"board":"weekly:2026-W01","n":5,"status":"ready","top":[]},{"board":"weekly:2026-W44","n":1,"status":"ready","top":[["u_new",10]]}],"final":{"alltime":{"status":"ready","top":[["u_new",10]]},"weekly:2026-W44":{"status":"ready","top":[["u_new",10]]}}}', 2, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdc_422'), 'Invalid reads: unknown board names and limits outside 1..100', '{"batchSize":3,"snapshot":{"asOfSeq":5,"boards":{"alltime":[["u_ana",50],["u_dung",50],["u_binh",30]],"weekly:2026-W44":[["u_dung",50],["u_chi",20],["u_ana",10]]}},"log":[{"userId":"u_ana","week":"2026-W43","points":40},{"userId":"u_binh","week":"2026-W43","points":30},{"userId":"u_chi","week":"2026-W44","points":20},{"userId":"u_ana","week":"2026-W44","points":10},{"userId":"u_dung","week":"2026-W44","points":50},{"userId":"u_binh","week":"2026-W44","points":30},{"userId":"u_chi","week":"2026-W44","points":40},{"userId":"u_em","week":"2026-W44","points":15}],"script":[{"read":"monthly","n":5},{"read":"weekly:44","n":5},{"read":"weekly:2026-W44:extra","n":5},{"read":"alltime","n":0},{"read":"alltime","n":101},{"read":"alltime","n":2.5},{"read":"alltime","n":"5"},{"tick":3},{"read":"Alltime","n":3},{"read":"alltime","n":100},{"read":"weekly:2026-W44","n":-1}]}', '{"reads":[{"board":"monthly","n":5,"status":"error","error":"unknown_board"},{"board":"weekly:44","n":5,"status":"error","error":"unknown_board"},{"board":"weekly:2026-W44:extra","n":5,"status":"error","error":"unknown_board"},{"board":"alltime","n":0,"status":"error","error":"invalid_limit"},{"board":"alltime","n":101,"status":"error","error":"invalid_limit"},{"board":"alltime","n":2.5,"status":"error","error":"invalid_limit"},{"board":"alltime","n":"5","status":"error","error":"invalid_limit"},{"board":"Alltime","n":3,"status":"error","error":"unknown_board"},{"board":"alltime","n":100,"status":"ready","top":[["u_binh",60],["u_chi",60],["u_ana",50],["u_dung",50],["u_em",15]]},{"board":"weekly:2026-W44","n":-1,"status":"error","error":"invalid_limit"}],"final":{"alltime":{"status":"ready","top":[["u_binh",60],["u_chi",60],["u_ana",50],["u_dung",50],["u_em",15]]},"weekly:2026-W43":{"status":"ready","top":[["u_ana",40],["u_binh",30]]},"weekly:2026-W44":{"statu